@CrossOrigin
@RestController
@RequestMapping("/InsurerQuery")
public class InsurerQueryRestController extends BaseSpringRestController {
	
	public InsurerQueryRestController( InsurerService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Insurer using a UUID
     * @param		UUID insurerId
     * @return		Insurer
     */    
    @GetMapping("/load")
    public Insurer load( @RequestParam(required=true) UUID insurerId ) {
    	Insurer entity = null;

    	try {  
    		entity = service.getInsurer( new InsurerFetchOneSummary( insurerId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Insurer using Id " + insurerId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Insurer business objects
     * @return		Set<Insurer>
     */
    @GetMapping("/")
    public List<Insurer> loadAll() {                
    	List<Insurer> insurerList = null;
        
    	try {
            // load the Insurer
            insurerList = service.getAllInsurer();
            
            if ( insurerList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Insurers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Insurers ", exc );
        	return null;
        }

        return insurerList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Insurer insurer = null;
    protected InsurerService service = null;
    private static final Logger LOGGER = Logger.getLogger(InsurerQueryRestController.class.getName());
    
}
